// Pagos pendientes que tocan recordar hoy
function aFecha(v) {
  if (!v) return null;
  v = String(v).trim();
  let m = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(v);
  return isNaN(d) ? null : d;
}
function normTel(t) {
  t = String(t || '').replace(/\D/g, '');
  if (t.length === 10 && t.startsWith('3')) t = '57' + t;
  return t;
}
const cfg = $('⚙️ Config').first().json;
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const MS_DIA = 86400000;

const salida = [];
for (const item of $input.all()) {
  const fila = item.json;
  const estado = String(fila.Estado || '').trim().toUpperCase();
  if (estado === 'PAGADO') continue;
  const tel = normTel(fila.Telefono);
  const vence = aFecha(fila.FechaVencimiento);
  if (!tel || !vence) continue;

  // días de mora: positivo = vencido, negativo = faltan días
  const diasMora = Math.round((hoy - vence) / MS_DIA);

  // aún no entra en ventana de recordatorio
  if (diasMora < -cfg.dias_antes_de_vencer) continue;

  // no repetir antes de la cadencia configurada
  const ultimo = aFecha(fila.UltimoRecordatorio);
  if (ultimo && Math.round((hoy - ultimo) / MS_DIA) < cfg.cada_cuantos_dias_recordar) continue;

  salida.push({ json: { ...fila, telefono_normalizado: tel, dias_mora: diasMora } });
}
return salida;

const pago = $('Loop Pagos').first().json;
const r = $json;
const mensaje = (r.message?.content || r.output || r.text || '').trim();
const hoy = new Date();
const fechaHoy = hoy.getFullYear() + '-' + String(hoy.getMonth() + 1).padStart(2, '0') + '-' + String(hoy.getDate()).padStart(2, '0');
return [{ json: { telefono: pago.telefono_normalizado, mensaje, row_number: pago.row_number, fechaHoy } }];
